   266→/// <summary>
   267→/// Validate Blob transactions in mempool version.
   268→/// </summary>
   269→public sealed class MempoolBlobTxValidator : ITxValidator
   270→{
   271→    public static readonly MempoolBlobTxValidator Instance = new();
   272→    private MempoolBlobTxValidator() { }
   273→
   274→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec)
   275→    {
   276→        return transaction switch
   277→        {
   278→            { NetworkWrapper: null } => ValidationResult.Success,
   279→            { Type: TxType.Blob, NetworkWrapper: ShardBlobNetworkWrapper wrapper } => ValidateBlobs(transaction, wrapper, releaseSpec),
   280→            { Type: TxType.Blob } or { NetworkWrapper: not null } => TxErrorMessages.InvalidTransactionForm,
   281→        };
   282→
   283→        static ValidationResult ValidateBlobs(Transaction transaction, ShardBlobNetworkWrapper wrapper, IReleaseSpec _)
   284→        {
   285→            IBlobProofsVerifier proofsManager = IBlobProofsManager.For(wrapper.Version);
   286→
   287→            return !proofsManager.ValidateLengths(wrapper) ? TxErrorMessages.InvalidBlobDataSize :
   288→                transaction.BlobVersionedHashes is null || !proofsManager.ValidateHashes(wrapper, transaction.BlobVersionedHashes) ? TxErrorMessages.InvalidBlobHashes :
   289→                !proofsManager.ValidateProofs(wrapper) ? TxErrorMessages.InvalidBlobProofs :
   290→                ValidationResult.Success;
   291→        }
   292→    }
   293→}
   294→
   295→/// <summary>
   296→/// Validate tx proof version in mempool version.
   297→/// </summary>
   298→public sealed class MempoolBlobTxProofVersionValidator : ITxValidator
   299→{
   300→    public static readonly MempoolBlobTxProofVersionValidator Instance = new();
   301→    private MempoolBlobTxProofVersionValidator() { }
   302→
   303→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec)
   304→    {
   305→        return transaction switch
   306→        {
   307→            LightTransaction lightTx => ValidateProofVersion(lightTx.ProofVersion, releaseSpec),
   308→            { Type: TxType.Blob, NetworkWrapper: ShardBlobNetworkWrapper wrapper } => ValidateProofVersion(wrapper.Version, releaseSpec),
   309→            { Type: TxType.Blob, NetworkWrapper: not null } => TxErrorMessages.InvalidTransactionForm,
   310→            _ => ValidationResult.Success,
   311→        };
   312→
   313→        static ValidationResult ValidateProofVersion(ProofVersion txProofVersion, IReleaseSpec spec) =>
   314→            txProofVersion != spec.BlobProofVersion ? new ValidationResult(TxErrorMessages.InvalidProofVersion, true) : ValidationResult.Success;
   315→    }
   316→}
   317→
   318→public abstract class BaseSignatureTxValidator : ITxValidator
   319→{
   320→    protected virtual ValidationResult ValidateChainId(Transaction transaction, IReleaseSpec releaseSpec) =>
   321→        releaseSpec.ValidateChainId ? TxErrorMessages.InvalidTxSignature : ValidationResult.Success;
   322→
   323→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec)
   324→    {
   325→        Signature? signature = transaction.Signature;
   326→        if (signature is null)
   327→        {
   328→            return TxErrorMessages.InvalidTxSignature;
   329→        }
   330→
   331→        UInt256 sValue = new(signature.SAsSpan, isBigEndian: true);
   332→        UInt256 rValue = new(signature.RAsSpan, isBigEndian: true);
   333→
   334→        UInt256 sMax = releaseSpec.IsEip2Enabled ? Secp256K1Curve.HalfNPlusOne : Secp256K1Curve.N;
   335→        return sValue.IsZero || sValue >= sMax ? TxErrorMessages.InvalidTxSignature
   336→            : rValue.IsZero || rValue >= Secp256K1Curve.NMinusOne ? TxErrorMessages.InvalidTxSignature
   337→            : signature.V is 27 or 28 ? ValidationResult.Success
   338→            : ValidateChainId(transaction, releaseSpec);
   339→    }
   340→}
   341→
   342→public sealed class LegacySignatureTxValidator(ulong chainId) : BaseSignatureTxValidator
   343→{
   344→    protected override ValidationResult ValidateChainId(Transaction transaction, IReleaseSpec releaseSpec)
   345→    {
   346→        ulong v = transaction.Signature!.V;
   347→        return releaseSpec.IsEip155Enabled && (v == chainId * 2 + 35ul || v == chainId * 2 + 36ul)
   348→            ? ValidationResult.Success
   349→            : base.ValidateChainId(transaction, releaseSpec);
   350→    }
   351→}
   352→
   353→public sealed class SignatureTxValidator : BaseSignatureTxValidator
   354→{
   355→    public static readonly SignatureTxValidator Instance = new();
   356→    private SignatureTxValidator() { }
   357→}
   358→
   359→public sealed class NoContractCreationTxValidator : ITxValidator
   360→{
   361→    public static readonly NoContractCreationTxValidator Instance = new();
   362→    private NoContractCreationTxValidator() { }
   363→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec) =>
   364→        transaction.IsContractCreation ? TxErrorMessages.NotAllowedCreateTransaction : ValidationResult.Success;
   365→}
   366→
   367→public sealed class AuthorizationListTxValidator : ITxValidator
   368→{
   369→    public static readonly AuthorizationListTxValidator Instance = new();
   370→    private AuthorizationListTxValidator() { }
   371→
   372→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec) =>
   373→        transaction.AuthorizationList switch
   374→        {
   375→            null or { Length: 0 } => TxErrorMessages.MissingAuthorizationList,
   376→            _ => ValidationResult.Success
   377→        };
   378→}
   379→
   380→public sealed class GasLimitCapTxValidator : ITxValidator
   381→{
   382→    public static readonly GasLimitCapTxValidator Instance = new();
   383→    private GasLimitCapTxValidator() { }
   384→
   385→    public ValidationResult IsWellFormed(Transaction transaction, IReleaseSpec releaseSpec)
   386→    {
   387→        long gasLimitCap = Eip7825Constants.GetTxGasLimitCap(releaseSpec);
   388→        return transaction.GasLimit > gasLimitCap ?
   389→            TxErrorMessages.TxGasLimitCapExceeded(transaction.GasLimit, gasLimitCap) : ValidationResult.Success;
   390→    }
   391→}
   392→

